import test from 'node:test';import assert from 'node:assert/strict';import {fileURLToPath} from 'node:url';import {proveBonusCanonicalAdvance,pinCanonicalRuntime,BONUS_HELD_CANONICAL} from './bonus-canonical-advance.mjs';
const repository=fileURLToPath(new URL('../..',import.meta.url));
test('independently proves entire actual canonical CI-only advancement while retaining original build identity',()=>{const proof=proveBonusCanonicalAdvance({repository,head:BONUS_HELD_CANONICAL});assert.equal(proof.pins.length,3);assert.notEqual(proof.head,proof.originalBuildController);assert.equal(proof.applicationMigrationAndGateInputsUnchanged,true);assert.equal(proof.releaseAuthorized,false);});
for(const head of ['0'.repeat(40),'dc74b804fcecb4bab3207e82c9b9f099b9bf13be'])test('refuses an unreviewed or rewound canonical head '+head,()=>assert.throws(()=>proveBonusCanonicalAdvance({repository,head})));
test('pin reconstruction refuses unrelated paths or missing/ambiguous anchors',()=>{assert.throws(()=>pinCanonicalRuntime('app/page.tsx',''));assert.throws(()=>pinCanonicalRuntime('.github/actions/setup-alpha/action.yml','unrelated'));assert.throws(()=>pinCanonicalRuntime('.github/workflows/alpha-staging.yml',"node-version: '22'"));});
